const ZOOM_DETECTION_THRESHOLD = .01;
const MAX_ROUNDING_ARTIFACT_SIZE = 1;
export function getAdjustedBaseContainerSize(rawContainerSize, baseContainerSize, baseContentSize) {
    const isZoomed = Math.abs(rawContainerSize - baseContainerSize) > .01;
    if (isZoomed && baseContentSize > baseContainerSize && baseContentSize - baseContainerSize <= 1) {
        return baseContentSize
    }
    return baseContainerSize
}
